<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\Holder\MessageSendAtAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the MessageSendAtAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class MessageSendAtAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getSendAt returns null on a freshly created holder.
     */
    public function testSendAtNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithMessageSendAtAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isSendAtAssigned());
        $this->assertNull($holder->getSendAt());
    }
}
class ImplWithMessageSendAtAttributeHolderUnitTest
{
    use MessageSendAtAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedSendAtRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultSendAt();
    }
}
